// HashMap — single thread only
HashMap<String,BigDecimal> hm = new HashMap<>();
hm.put(null, v);          // null key allowed
// concurrent write → silent corruption (no CME guarantee)

// ConcurrentHashMap — thread-safe
ConcurrentHashMap<String,BigDecimal> chm =
    new ConcurrentHashMap<>();
// chm.put(null,..) → NullPointerException (no null)

void debit(String acct, BigDecimal amt){
  chm.compute(acct, (k,bal) ->            // atomic, bucket-locked
      bal.subtract(amt));
}
BigDecimal read(String acct){
  return chm.get(acct);                   // lock-free (volatile)
}
// iterator: weakly-consistent, never throws CME
```
